export function getQuestionsByUE(ueId) {
  return allQuestions.filter((question) => question.ue === ueId);
}

export function getQuestionsBySemester(semester) {
  return allQuestions.filter((question) => question.semester === semester);
}

export function getQuestionCountByUE(ueId) {
  return allQuestions.filter((question) => question.ue === ueId).length;
}

export function getQuestionsByDifficulty(difficulty) {
  return allQuestions.filter((question) => question.difficulty === difficulty);
}

export function getQuestionsByTheme(theme) {
  return allQuestions.filter((question) => question.theme === theme);
}

export function getRandomQuestions(questions, amount) {
  if (!Array.isArray(questions)) return [];
  const shuffled = [...questions];
  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  const safeAmount = Math.max(0, Number(amount) || 0);
  return shuffled.slice(0, Math.min(safeAmount, shuffled.length));
}

export function getQuestionById(questionId) {
  return allQuestions.find((question) => question.id === questionId) || null;
}

export function getThemesByUE(ueId) {
  return [...new Set(getQuestionsByUE(ueId).map((question) => question.theme))].sort();
}

export function getTotalQuestionCount() {
  return allQuestions.length;
}
